return $input.all().map(item => {
  try {
    // Get the AI response from the text field.
    const raw = String(item.json.text ?? "").trim();

    // Remove Markdown code fences if present.
    const cleaned = raw.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");

    // Parse the AI-generated JSON string.
    const recipe = JSON.parse(cleaned);

    // Check the status returned by the AI.
    const status = recipe.status === true;

    // Extract only the recipe message.
    const message = status && typeof recipe.message === "string"
      ? recipe.message.trim()
      : "Please provide a valid recipe name.";

    // Return clean data for Slack.
    return {
      json: {
        status,
        recipe_name: status ? String(recipe.recipe_name ?? "") : "",
        message,
        channel: $("Slack Trigger").first().json.channel
      }
    };
  } catch (error) {
    // Return a safe message if the AI response isn't valid JSON.
    return {
      json: {
        status: false,
        recipe_name: "",
        message: "Sorry, I couldn't process your recipe. Please try again.",
        channel: $("Slack Trigger").first().json.channel
      }
    };
  }
});
